function notReached(
  id: string,
  tabLabel: string,
  title: string,
  reason: string,
): ResultData {
  return {
    id,
    tabLabel,
    title,
    subsections: [
      {
        id: `${id}-not-reached`,
        observations: reason,
      },
    ],
  };
}

